DROP TABLE IF EXISTS `oxcontents`;
CREATE TABLE `oxcontents` (
                              `OXID` char(32) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL COMMENT 'Content id',
                              `OXLOADID` char(32) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '' COMMENT 'Id, specified by admin and can be used instead of oxid',
                              `OXSHOPID` int(11) NOT NULL DEFAULT '1' COMMENT 'Shop id (oxshops)',
                              `OXSNIPPET` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Snippet (can be included to other oxcontents records)',
                              `OXTYPE` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Type: 0 - Snippet, 1 - Upper Menu, 2 - Category, 3 - Manual',
                              `OXACTIVE` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Active (multilanguage)',
                              `OXACTIVE_1` tinyint(1) NOT NULL DEFAULT '0',
                              `OXPOSITION` varchar(32) NOT NULL DEFAULT '' COMMENT 'Position',
                              `OXTITLE` varchar(255) NOT NULL DEFAULT '' COMMENT 'Title (multilanguage)',
                              `OXCONTENT` mediumtext NOT NULL COMMENT 'Content (multilanguage)',
                              `OXTITLE_1` varchar(255) NOT NULL DEFAULT '',
                              `OXCONTENT_1` mediumtext NOT NULL,
                              `OXACTIVE_2` tinyint(1) NOT NULL DEFAULT '0',
                              `OXTITLE_2` varchar(255) NOT NULL DEFAULT '',
                              `OXCONTENT_2` mediumtext NOT NULL,
                              `OXACTIVE_3` tinyint(1) NOT NULL DEFAULT '0',
                              `OXTITLE_3` varchar(255) NOT NULL DEFAULT '',
                              `OXCONTENT_3` mediumtext NOT NULL,
                              `OXCATID` varchar(32) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL COMMENT 'Category id (oxcategories), used only when type = 2',
                              `OXFOLDER` varchar(32) NOT NULL DEFAULT '' COMMENT 'Content Folder (available options at oxconfig.OXVARNAME = aCMSfolder)',
                              `OXTERMVERSION` char(32) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '' COMMENT 'Term and Conditions version (used only when OXLOADID = oxagb)',
                              `OXTIMESTAMP` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Timestamp',
                              PRIMARY KEY (`OXID`),
                              UNIQUE KEY `OXLOADID` (`OXLOADID`,`OXSHOPID`),
                              KEY `cat_search` (`OXTYPE`,`OXSHOPID`,`OXSNIPPET`,`OXCATID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Content pages (Snippets, Menu, Categories, Manual)';

TRUNCATE `oxcontents`;
INSERT INTO `oxcontents` (`OXID`, `OXLOADID`, `OXSHOPID`, `OXSNIPPET`, `OXTYPE`, `OXACTIVE`, `OXACTIVE_1`, `OXPOSITION`, `OXTITLE`, `OXCONTENT`, `OXTITLE_1`, `OXCONTENT_1`, `OXACTIVE_2`, `OXTITLE_2`, `OXCONTENT_2`, `OXACTIVE_3`, `OXTITLE_3`, `OXCONTENT_3`, `OXCATID`, `OXFOLDER`, `OXTERMVERSION`, `OXTIMESTAMP`) VALUES
                                                                                                                                                                                                                                                                                                                            ('1074279e67a85f5b1.96907412',	'oxorderinfo',	1,	1,	0,	1,	1,	'',	'Wie bestellen?',	'<div>Beispieltext:</div>\r\n<div> </div>\r\n<div>{{  oxcmp_shop.oxshops__oxname.value  }}, Ihr Online-Shop für ... <br />\r\n<br />\r\nBei uns haben Sie die Wahl aus mehr als ... Artikeln von bester Qualität und namhaften Herstellern. Schauen Sie sich um, stöbern Sie in unseren Angeboten! <br />\r\n{{  oxcmp_shop.oxshops__oxname.value  }} steht Ihnen im Internet rund um die Uhr und 7 Tage die Woche offen.<br />\r\n<br />\r\nWenn Sie eine Bestellung aufgeben möchten, können Sie das:\r\n<ul>\r\n<li class=\"font11\">direkt im Internet über unseren Shop </li>\r\n<li class=\"font11\">per Fax unter {{  oxcmp_shop.oxshops__oxtelefax.value  }} </li>\r\n<li class=\"font11\">per Telefon unter {{  oxcmp_shop.oxshops__oxtelefon.value  }} </li>\r\n<li class=\"font11\">oder per E-Mail unter <a href=\"mailto:{{  oxcmp_shop.oxshops__oxowneremail.value  }}?subject=Bestellung\"><strong>{{  oxcmp_shop.oxshops__oxowneremail.value  }}</strong></a> </li></ul>Telefonisch sind wir für Sie <br />\r\nMontag bis Freitag von 10 bis 18 Uhr erreichbar. <br />\r\nWenn Sie auf der Suche nach einem Artikel sind, der zum Sortiment von {{  oxcmp_shop.oxshops__oxname.value  }} passen könnte, ihn aber nirgends finden, lassen Sie es uns wissen. Gern bemühen wir uns um eine Lösung für Sie. <br />\r\n<br />\r\nSchreiben Sie an <a href=\"mailto:{{  oxcmp_shop.oxshops__oxowneremail.value  }}?subject=Produktidee\"><strong>{{  oxcmp_shop.oxshops__oxowneremail.value  }}</strong></a>.</div>',	'How to order?',	'<h1>Text Example</h1>\r\n<h2>{{  oxcmp_shop.oxshops__oxname.value  }}, your online store for ...</h2>\r\n<p>With us, you can choose from more than ... products of high quality and reputable manufacturers. Take a look around and browse through our offers!<br />\r\nOn the internet {{  oxcmp_shop.oxshops__oxname.value  }} is open 24/7.</p>\r\n<p>If you want to place an order you can purchase</p>\r\n<ul>\r\n<li class=\"font11\">via our online store</li>\r\n<li class=\"font11\">via fax {{  oxcmp_shop.oxshops__oxtelefax.value  }} </li>\r\n<li class=\"font11\">via telephone {{  oxcmp_shop.oxshops__oxtelefon.value  }} </li>\r\n<li class=\"font11\">or via e-mail <a href=\"mailto:{{  oxcmp_shop.oxshops__oxowneremail.value  }}?subject=Order\"><strong>{{  oxcmp_shop.oxshops__oxowneremail.value  }}</strong></a></li></ul>\r\n<p>By telephone, we are available<br />\r\nMonday to Friday 10 AM thru 6 PM. </p>\r\n<p>If you are looking for an item that did not match the range of {{  oxcmp_shop.oxshops__oxname.value  }}, let\'s us know. We are happy to find a solution for you.</p>\r\n<p>Write to <a href=\"mailto:{{  oxcmp_shop.oxshops__oxowneremail.value  }}?subject=Product idea\"><strong>{{  oxcmp_shop.oxshops__oxowneremail.value  }}</strong></a></p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('1544167b4666ccdc1.28484600',	'oxblocked',	1,	1,	0,	1,	1,	'',	'Benutzer geblockt',	'<div><span style=\"color: #ff0000;\"><strong>Der Zugang wurde Ihnen verweigert!</strong></span></div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>',	'user blocked',	'<div>\r\n   <span style=\"color: #ff0000;\"><strong>Permission denied!</strong></span>\r\n</div>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
