                                                                                                                                                                                                                                                                                                                            ('220404cee0caf470e227c1c9f1ec4ae2',	'oxrighttocancellegend',	1,	1,	0,	1,	1,	'',	'AGB und Widerrufsrecht',	'{% ifcontent ident \"oxagb\" set oCont %}\r\n    Ich habe die <a id=\"test_OrderOpenAGBBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'agb_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\" class=\"fontunderline\">AGB</a> gelesen und erkläre mich mit ihnen einverstanden.&nbsp;\r\n{% endifcontent %}\r\n{% ifcontent ident \"oxrightofwithdrawal\" set oCont %}\r\n    Ich wurde über mein <a id=\"test_OrderOpenWithdrawalBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'rightofwithdrawal_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\">{{  oCont.oxcontents__oxtitle.value  }}</a> informiert.\r\n{% endifcontent %}',	'Terms and Conditions and Right to Withdrawal',	'{% ifcontent ident \"oxagb\" set oCont %} I agree to the <a id=\"test_OrderOpenAGBBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'agb_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\" class=\"fontunderline\">Terms and Conditions</a>.&nbsp;\r\n{% endifcontent %}\r\n{% ifcontent ident \"oxrightofwithdrawal\" set oCont %}\r\n    I have been informed about my <a id=\"test_OrderOpenWithdrawalBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'rightofwithdrawal_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\">{{  oCont.oxcontents__oxtitle.value  }}</a>.\r\n{% endifcontent %}',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('220404cee0caf470e227c1c9f1ec4ae3',	'oxrighttocancellegend2',	1,	1,	0,	1,	1,	'',	'AGB und Widerrufsrecht',	'{% ifcontent ident \"oxagb\" set oCont %}\r\n    Es gelten unsere <a rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'agb_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\" class=\"fontunderline\">Allgemeinen Geschäftsbedingungen</a>.&nbsp;\r\n{% endifcontent %}\r\n{% ifcontent ident \"oxrightofwithdrawal\" set oCont %}\r\n    Hier finden Sie <a id=\"test_OrderOpenWithdrawalBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'rightofwithdrawal_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\">Einzelheiten zum Widerrufsrecht</a>.\r\n{% endifcontent %}',	'Terms and Conditions and Right to Withdrawal',	'{% ifcontent ident \"oxagb\" set oCont %} Our general <a rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'agb_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\" class=\"fontunderline\">terms and conditions</a> apply.&nbsp;\r\n{% endifcontent %}\r\n{% ifcontent ident \"oxrightofwithdrawal\" set oCont %}\r\n    Read details about  <a id=\"test_OrderOpenWithdrawalBottom\" rel=\"nofollow\" href=\"{{  oCont.getLink()  }}\" onclick=\"window.open(\'{{  oCont.getLink()|add_url_parameters(\"plain=1\") }}\', \'rightofwithdrawal_popup\', \'resizable=yes,status=no,scrollbars=yes,menubar=no,width=620,height=400\');return false;\">right of withdrawal</a>.\r\n{% endifcontent %}',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('220404cee0caf470e227c1c9f1ec4aL3',	'oxdownloadableproductsagreement',	1,	1,	0,	1,	1,	'',	'Für digitale Inhalte',	'Ja, ich möchte sofort Zugang zu dem digitalen Inhalt und weiß, dass mein Widerrufsrecht mit dem Zugang erlischt.',	'For the supply of digital content',	'I want immediate access to the digital content and I acknowledge that thereby I lose my right to cancel once the service has begun.',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('220404cee0caf470e227c1c9f1ec4aL4',	'oxserviceproductsagreement',	1,	1,	0,	1,	1,	'',	'Für Dienstleistungen',	'Ja, bitte beginnen Sie sofort mit der Dienstleistung. Mein Widerrufsrecht erlischt mit vollständiger Ausführung.',	'For service contracts',	'I agree to the starting of the service and I acknowledge that I lose my right to cancel once the service has been fully performed.',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('29142e76dd32dd477.41262508',	'oxforgotpwd',	1,	1,	0,	1,	1,	'',	'Passwort vergessen',	'Sollten Sie innerhalb der nächsten Minuten KEINE E-Mail mit Ihren Zugangsdaten erhalten, so überprüfen Sie bitte: Haben Sie sich in unserem Shop bereits registriert? Wenn nicht, so tun Sie dies bitte einmalig im Rahmen des Bestellprozesses. Sie können dann selbst ein Passwort festlegen. Sobald Sie registriert sind, können Sie sich in Zukunft mit Ihrer E-Mail-Adresse und Ihrem Passwort einloggen.\r\n<ul>\r\n<li class=\"font11\">Wenn Sie sich sicher sind, dass Sie sich in unserem Shop bereits registriert haben, dann überprüfen Sie bitte, ob Sie sich bei der Eingabe Ihrer E-Mail-Adresse evtl. vertippt haben.</li></ul>\r\n<p>Sollten Sie trotz korrekter E-Mail-Adresse und bereits bestehender Registrierung weiterhin Probleme mit dem Login haben und auch keine \"Passwort vergessen\"-E-Mail erhalten, so wenden Sie sich bitte per E-Mail an: <a href=\"mailto:{{  oxcmp_shop.oxshops__oxinfoemail.value  }}?subject=Passwort\"><strong>{{  oxcmp_shop.oxshops__oxinfoemail.value  }}</strong></a></p>',	'Forgot password',	'<p>If you don\'t get an e-mail with your access data, please make sure that you have already registered with us. As soon as you are registered, you can login with your e-mail address and your password.</p>\r\n<ul>\r\n<li>\r\nIf you are sure you are already registered, please check the e-mail address you entered as user name.</li></ul>\r\n<p>\r\nIn case you still have problems logging in, please turn to us by e-mail: <a href=\"mailto:{{  oxcmp_shop.oxshops__oxinfoemail.value  }}?subject=Password\"><strong>{{  oxcmp_shop.oxshops__oxinfoemail.value  }}</strong></a></p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('2eb46767947d21851.22681675',	'oximpressum',	1,	1,	0,	1,	1,	'',	'Impressum',	'<p>Fügen Sie hier Ihre Anbieterkennzeichnung ein.</p>',	'About Us',	'<p>Add provider identification here.</p>',	1,	'',	'',	0,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('2eb4676806a3d2e87.06076523',	'oxagb',	1,	1,	0,	1,	1,	'',	'AGB',	'<div><strong>AGB</strong></div>\r\n<div><strong>&nbsp;</strong></div>\r\n<div>Fügen Sie hier Ihre allgemeinen Geschäftsbedingungen ein:</div>\r\n<div>&nbsp;</div>\r\n<div><span style=\"font-weight: bold\">Strukturvorschlag:</span><br>\r\n<br>\r\n<ol>\r\n<li>Geltungsbereich </li>\r\n<li>Vertragspartner </li>\r\n<li>Angebot und Vertragsschluss </li>\r\n<li>Widerrufsrecht, Widerrufsbelehrung, Widerrufsfolgen </li>\r\n<li>Preise und Versandkosten </li>\r\n<li>Lieferung </li>\r\n<li>Zahlung </li>\r\n<li>Eigentumsvorbehalt </li>\r\n<li>Gewährleistung </li>\r\n<li>Weitere Informationen</li></ol></div>',	'Terms and Conditions',	'Insert your terms and conditions here.',	1,	'',	'',	0,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'1',	'2024-12-06 12:20:29'),
