                                                                                                                                                                                                                                                                                                                            ('460273f2ae78b9c40c536a1c331317ee',	'oxregisterplainaltemail',	1,	1,	0,	1,	1,	'',	'Alternative E-Mail zur Registrierung PLAIN',	'Hallo {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }},\r\n\r\ndanke für die Registrierung im {{  shop.oxshops__oxname.getRawValue()  }}!\r\nVon jetzt an können Sie sich mit Ihrer E-Mail-Adresse {{  user.oxuser__oxusername.value  }}.\r\n\r\nFolgen Sie diesem Link, um die Registrierung zu bestätigen:\r\n{{  oViewConf.getBaseDir()  }}index.php?cl=register&fnc=confirmRegistration&uid={{  user.getUpdateId()  }}&amp;lang={{  oViewConf.getActLanguageId()  }}&shp={{  shop.oxshops__oxid.value  }}\r\n\r\nSie können diesen Link in den nächsten {{  user.getUpdateLinkTerm() / 3600  }} Stunden verwenden.</p>\r\n\r\n\r\nIhr Team vom {{  shop.oxshops__oxname.getRawValue()  }}',	'Alternative Registration Email PLAIN',	'Hello, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }},\r\n\r\nthanks for your registration at {{  shop.oxshops__oxname.getRawValue()  }}!\r\nFrom now on, you can log in with your email address {{  user.oxuser__oxusername.value  }}.\r\n\r\nFollow this link to confirm your registration:\r\n{{  oViewConf.getBaseDir()  }}index.php?cl=register&fnc=confirmRegistration&uid={{  user.getUpdateId()  }}&amp;lang={{  oViewConf.getActLanguageId()  }}&shp={{  shop.oxshops__oxid.value  }}\r\n\r\nYou can use this link within the next {{  user.getUpdateLinkTerm() / 3600  }} hours.<br />\r\n\r\n\r\nYour {{  shop.oxshops__oxname.getRawValue()  }} team',	1,	'',	'',	1,	