 />\r\nYour {{  shop.oxshops__oxname.value  }} team<br />',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
