                                                                                                                                                                                                                                                                                                                            ('ad542e49975709a72.52261121',	'oxnewsletteremail',	1,	1,	0,	1,	1,	'',	'Newsletter eShop',	'Hallo, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.value  }} {{  user.oxuser__oxlname.value  }},<br>\r\nvielen Dank für Ihre Anmeldung zu unserem Newsletter.<br>\r\n<br>\r\nUm den Newsletter freizuschalten klicken Sie bitte auf folgenden Link:<br>\r\n<br>\r\n<a href=\"{{ subscribeLink|raw }}\">{{ subscribeLink|raw }}</a><br>\r\n<br>\r\nIhr {{  shop.oxshops__oxname.value  }} Team<br>',	'newsletter confirmation',	'Hello, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.value  }} {{  user.oxuser__oxlname.value  }},<br>\r\nthank you for your newsletter subscription.<br>\r\n<br>\r\nFor final registration, please click on this link:<br>\r\n<br>\r\n<a href=\"{{ subscribeLink|raw }}\">{{ subscribeLink|raw }}</a><br>\r\n<br>\r\nYour {{  shop.oxshops__oxname.value  }} Team<br>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('ad542e4999ec01dd3.07214049',	'oxnewsletterplainemail',	1,	1,	0,	1,	1,	'',	'Newsletter eShop Plain',	'{{  shop.oxshops__oxname.getRawValue()  }} Newsletter Hallo, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }}, vielen Dank für Ihre Anmeldung zu unserem Newsletter. Um den Newsletter freizuschalten klicken Sie bitte auf folgenden Link: {{ subscribeLink|raw }} Ihr {{  shop.oxshops__oxname.getRawValue()  }} Team',	'newsletter confirmation plain',	'{{  shop.oxshops__oxname.getRawValue()  }} Newsletter \r\n\r\nHello, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }}, \r\n\r\nthank you for your newsletter subscription. For final registration, please click on this link: \r\n{{ subscribeLink }} \r\n\r\nYour {{  shop.oxshops__oxname.getRawValue()  }} Team',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('ad542e49ae50c60f0.64307543',	'oxuserorderemail',	1,	1,	0,	1,	1,	'',	'Ihre Bestellung',	'Vielen Dank für Ihre Bestellung!<br>\r\n<br>\r\nNachfolgend haben wir zur Kontrolle Ihre Bestellung noch einmal aufgelistet.<br>\r\nBei Fragen sind wir jederzeit für Sie da: Schreiben Sie einfach an {{  shop.oxshops__oxorderemail.value  }}!<br>\r\n<br>',	'your order',	'Thank you for your order!<br />\r\n<br />\r\nBelow, we have listed your order.<br />\r\nIf you have any questions, don\'t hesitate to drop us an e-mail {{  shop.oxshops__oxorderemail.value  }}!<br />\r\n<br />',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
