                                                                                                                                                                                                                                                                                                                            ('ad542e49c8ec04201.39247735',	'oxregisteremail',	1,	1,	0,	1,	1,	'',	'Vielen Dank für Ihre Registrierung',	'Hallo, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.value  }} {{  user.oxuser__oxlname.value  }}, vielen Dank für Ihre Registrierung bei {{  shop.oxshops__oxname.value  }}!<br>\r\n<br>\r\nSie können sich ab sofort auch mit Ihrer E-Mail-Adresse <strong>{{  user.oxuser__oxusername.value  }}</strong> einloggen.<br>\r\n<br>\r\nIhr {{  shop.oxshops__oxname.value  }} Team<br>',	'thanks for your registration',	'Hello, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.value  }} {{  user.oxuser__oxlname.value  }}, <br />\r\n<br />\r\n<p>\r\nthank you for your registration at {{  shop.oxshops__oxname.value  }}!</p>\r\nFrom now on, you can log in with your email address <strong>{{  user.oxuser__oxusername.value  }}</strong>.<br />\r\n<br />\r\nYour {{  shop.oxshops__oxname.value  }} team<br />',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('ad542e49ca4750015.09588134',	'oxregisterplainemail',	1,	1,	0,	1,	1,	'',	'Vielen Dank für Ihre Registrierung Plain',	'<p>{{  shop.oxshops__oxregistersubject.getRawValue()  }} Hallo, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }}, vielen Dank für Ihre Registrierung bei {{  shop.oxshops__oxname.getRawValue()  }}! Sie können sich ab sofort auch mit Ihrer E-Mail-Adresse ({{  user.oxuser__oxusername.value  }}) einloggen. Ihr {{  shop.oxshops__oxname.getRawValue()  }} Team</p>',	'thanks for your registration plain',	'<p>Hello, {{  user.oxuser__oxsal.value|translate_salutation  }} {{  user.oxuser__oxfname.getRawValue()  }} {{  user.oxuser__oxlname.getRawValue()  }},\r\n\r\nthank you for your registration at {{  shop.oxshops__oxname.getRawValue()  }}!\r\nFrom now on, you can log in with your email address {{  user.oxuser__oxusername.value  }}.\r\n\r\nYour {{  shop.oxshops__oxname.getRawValue()  }} team</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
