                                                                                                                                                                                                                                                                                                                            ('c4241316b2e5c1966.96997011',	'oxhelpalist',	1,	1,	0,	1,	1,	'',	'Hilfe - Die Produktliste',	'<p>Hier können zusätzliche Informationen, weiterführende Links, Bedienungshinweise etc. für die Hilfe-Funktion in den <em>Produktlisten</em> eingefügt werden. </p>',	'Help - Product List',	'<p>Here, you can insert additional information, further links, user manual etc. for the &quot;Help&quot;-function on <em>product pages</em>.</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c4241316b2e5c1966.96997012',	'oxhelpdefault',	1,	1,	0,	1,	1,	'',	'Hilfe - Main',	'<p>Hier können zusätzliche Informationen, weiterführende Links, Bedienungshinweise etc. für die Hilfe-Funktion in der <em>Kategorieansicht</em> eingefügt werden. </p>',	'Help - Main',	'<p>Here, you can insert additional information, further links, user manual etc. for the &quot;Help&quot;-function on <em>category pages</em>.</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c4241316b2e5c1966.96997013',	'oxhelpstart',	1,	1,	0,	1,	1,	'',	'Hilfe - Die Startseite',	'<p>Hier können zusätzliche Informationen, weiterführende Links, Bedienungshinweise etc. für die Hilfe-Funktion auf der <em>Startseite</em> eingefügt werden. </p>\r\n<p>&nbsp;</p>',	'Help - Start page',	'<p>Here, you can insert additional information, further links, user manual etc. for the &quot;Help&quot;-function on the <em>start page</em>.</p><br />',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c4241316c6e7b9503.93160420',	'oxbargain',	1,	1,	0,	1,	1,	'',	'Angebot der Woche',	'<table>{% for articlebargain_item in oView.getBargainArticleList() %} <tbody><tr><td>\r\n<div class=\"product_image_s_container\"><a href=\"{{ articlebargain_item.getLink() }}\"><img border=\"0\" alt=\"{{  articlebargain_item.oxarticles__oxtitle.value  }}{% if articlebargain_item.oxarticles__oxvarselect.value  %} {{  articlebargain_item.oxarticles__oxvarselect.value  }}{% endif %} {{ oxcmp_shop.oxshops__oxtitlesuffix.value }}\" src=\"{{  articlebargain_item.getDynImageDir() }}/{{ articlebargain_item.oxarticles__oxicon.value }}\"></a></div> </td><td class=\"boxrightproduct-td\"> <a href=\"{{ articlebargain_item.getLink() }}\" class=\"boxrightproduct-td\"><strong>{{  articlebargain_item.oxarticles__oxtitle.value|cat(\"\r\n\")|cat(articlebargain_item.oxarticles__oxvarselect.value)|striptags|smart_wordwrap(15, \"<br>\r\n\", 2, 1, \"...\")  }}</strong></a><br>\r\n {% if articlebargain_item.isBuyable()  %} <a href=\"{{ articlebargain_item.getToBasketLink() }}&amp;am=1\" class=\"details\" onclick=\"showBasketWnd();\" rel=\"nofollow\"><img border=\"0\" src=\"{{ oViewConf.getImageUrl(\'arrow_details.gif\') }}\" alt=\"\"> Jetzt bestellen! </a> {% endif %} </td></tr>{% endfor %}\r\n</tbody></table>',	'Week\'s Special',	'<table>{% for articlebargain_item in oView.getBargainArticleList() %} <tbody><tr><td>\r\n<div class=\"product_image_s_container\"><a href=\"{{ articlebargain_item.getLink() }}\"><img border=\"0\" src=\"{{  articlebargain_item.getDynImageDir() }}/{{ articlebargain_item.oxarticles__oxicon.value }}\" alt=\"{{  articlebargain_item.oxarticles__oxtitle.value  }}{% if articlebargain_item.oxarticles__oxvarselect.value  %} {{  articlebargain_item.oxarticles__oxvarselect.value  }}{% endif %} {{ oxcmp_shop.oxshops__oxtitlesuffix.value }}\"></a></div> </td><td class=\"boxrightproduct-td\"> <a class=\"boxrightproduct-td\" href=\"{{ articlebargain_item.getLink() }}\"><strong>{{  articlebargain_item.oxarticles__oxtitle.value|cat(\"\r\n\")|cat(articlebargain_item.oxarticles__oxvarselect.value)|striptags|smart_wordwrap(15, \"<br>\r\n) \":2:1:\"...\"  }}</strong></a><br>\r\n {% if articlebargain_item.isBuyable() %} <a onclick=\"showBasketWnd();\" class=\"details\" href=\"{{ articlebargain_item.getToBasketLink() }}&amp;am=1\" rel=\"nofollow\"><img border=\"0\" alt=\"\" src=\"{{ oViewConf.getImageUrl(\'arrow_details.gif\') }}\"> Order now! </a> {% endif %} </td></tr>{% endfor %} </tbody></table>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c8d45408c08bbaf79.09887022',	'oxuserordernpemail',	1,	1,	0,	1,	1,	'',	'Ihre Bestellung (Fremdländer)',	'<div>Vielen Dank für Ihre Bestellung!</div>\r\n<p><strong><span style=\"color: #ff0000\">Hinweis:</span></strong> Derzeit ist uns keine Versandmethode für dieses Land bekannt. Wir werden versuchen, Versandmethoden zu finden und Sie über das Ergebnis unter Angabe der Versandkosten informieren. </p>Bei Fragen sind wir jederzeit für Sie da: Schreiben Sie einfach an {{  shop.oxshops__oxorderemail.value  }}! <br />\r\n<br />',	'your order (other country)',	'<p>Thank you for your order!</p>\r\n<p><strong><span style=\"color: #ff0000\">Information:</span></strong> Currently, there is no shipping method defined for your country. We will find a method to deliver the goods you purchased and will inform you as soon as possible.</p>\r\n<p>If you have any requests, don\'t hesitate to contact us! {{  shop.oxshops__oxorderemail.value  }}</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c8d45408c4998f421.15746968',	'oxadminordernpemail',	1,	1,	0,	1,	1,	'',	'Ihre Bestellung Admin (Fremdländer)',	'<div>\r\n<p> <span style=\"color: #ff0000;\"><strong>Hinweis:</strong></span> Derzeit ist keine Liefermethode für dieses Land bekannt. Bitte Liefermöglichkeiten suchen und den Besteller unter Angabe der <strong>Lieferkosten</strong> informieren!\r\n&nbsp;</p> </div>\r\n<div>Folgende Artikel wurden soeben unter {{  shop.oxshops__oxname.value  }} bestellt:<br>\r\n<br>\r\n</div>',	'your order admin (other country)',	'<p> <span style=\"color: #ff0000\"><strong>Information:</strong></span> Currently, there is no shipping method defined for this country. Please find a delivery option and inform the customer about the <strong>shipping costs</strong>.</p>\r\n<p>The following products have been ordered on {{  shop.oxshops__oxname.value  }}:<br />\r\n<br /></p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c8d45408c5c39ea22.75925645',	'oxuserordernpplainemail',	1,	1,	0,	1,	1,	'',	'Ihre Bestellung (Fremdländer) Plain',	'Vielen Dank für Ihre Bestellung!\r\n\r\nHinweis: Derzeit ist uns keine Versandmethode für dieses Land bekannt. Wir werden versuchen, Versandmethoden zu finden und Sie über das Ergebnis unter Angabe der Versandkosten informieren.\r\n\r\nBei Fragen sind wir jederzeit für Sie da: Schreiben Sie einfach an {{  shop.oxshops__oxorderemail.value  }}!',	'your order plain (other country)',	'Thank you for your order!\r\nInformation: Currently, there is no shipping method defined for your country. We will find a method to deliver the goods you purchased and will inform you as soon as possible.\r\n\r\nIf you have any requests don\'t hesitate to contact us! {{  shop.oxshops__oxorderemail.value  }}',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('c8d45408c718782f3.21298666',	'oxadminordernpplainemail',	1,	1,	0,	1,	1,	'',	'Ihre Bestellung Admin (Fremdländer) Plain',	'Hinweis: Derzeit ist keine Liefermethode für dieses Land bekannt. Bitte Liefermöglichkeiten suchen und den Besteller informieren!\r\n\r\nFolgende Artikel wurden soeben unter {{  shop.oxshops__oxname.getRawValue()  }} bestellt:',	'your order admin plain (other country)',	'<p>Information: Currently, there is no shipping method defined for this country. Please find a delivery option and inform the customer about the shipping costs.\r\n\r\nThe following products have been ordered on {{  shop.oxshops__oxname.getRawValue()  }}:</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_EMAILS',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('ce77743c334edf92b0cab924a7',	'oxstartmetakeywords',	1,	1,	0,	1,	1,	'',	'META Keywords Startseite',	'kite, kites, kiteboarding, kiteboards, wakeboarding, wakeboards, boards, strand, sommer, wassersport, mode, fashion, style, shirts, jeans, accessoires, angebote',	'META keywords start page',	'kite, kites, kiteboarding, kiteboards, wakeboarding, wakeboards, boards, beach, summer, watersports, funsports, fashion, style, shirts, jeans, accessories, special offers',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('ce79015b6f6f07612270975889',	'oxstartmetadescription',	1,	1,	0,	1,	1,	'',	'META Description Startseite',	'Alles zum Thema Wassersport, Sportbekleidung und Mode. Umfangreiches Produktsortiment mit den neusten Trendprodukten. Blitzschneller Versand.<br />',	'META description start page',	'<p>All about watersports, sportswear and fashion. Extensive product range including several trendy products. Fast shipping.</p>\r\n<p>&nbsp;</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('d0f7ac8b29909908dc20d854224944fe',	'oxnopaymentmethod',	1,	1,	0,	1,	1,	'',	'No payment method text',	'<p>Derzeit ist keine Versandart für dieses Land\r\ndefiniert.</p>\r\n<p>Wir werden versuchen, Liefermöglichkeiten zu\r\nfinden und Sie über die Versandkosten informieren.</p>',	'No payment method text',	'<p>Currently we have no shipping method set up\r\nfor this country.</p>\r\n<p>We are aiming to find a possible delivery\r\nmethod and we will inform you as soon as possible via e-mail about the result,\r\nincluding further information about delivery costs.</p>',	0,	'',	'',	0,	'',	'',	'30e44ab83fdee7564.23264141',	'',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('d74fdc1ed22a0d469bdcc5f003ca6575',	'oxregistrationdescription',	1,	1,	0,	1,	1,	'',	'Registration Description',	'<p>Mit einem persönlichen Kundenkonto haben Sie folgende Vorteile:<br />\r\n - Verwaltung der Lieferadressen<br />\r\n - Prüfung des Bestellstatus<br />\r\n - Bestellhistorie<br />\r\n - persönlicher Merkzettel<br />\r\n - persönliche Wunschliste<br />\r\n - Newsletter-Verwaltung<br />\r\n - Sonder- und Rabattaktionen</p>',	'Registration Description',	'<p>A customer with an account has advantages like:<br />\r\n - Administration of shipping addresses<br />\r\n - Check order status<br />\r\n - Order History<br />\r\n - Personal Wish List<br />\r\n - Personal Gift Registry<br />\r\n - Newsletter subscription<br />\r\n - Special offers and discounts</p>',	0,	'',	'',	0,	'',	'',	'30e44ab83fdee7564.23264141',	'',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('f41427a07519469f1.34718981',	'oxdeliveryinfo',	1,	1,	0,	1,	1,	'',	'Zahlung und Lieferung',	'<p>Fügen Sie hier Ihre Versandinformationen und -kosten ein.</p>',	'Shipping and Charges',	'<p>Add your shipping information and costs here.</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('f41427a099a603773.44301043',	'oxsecurityinfo',	1,	1,	0,	1,	1,	'',	'Datenschutz',	'Fügen Sie hier Ihre Datenschutzbestimmungen ein.',	'Privacy Policy',	'Enter your privacy policy here.',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29'),
                                                                                                                                                                                                                                                                                                                            ('f41427a10afab8641.52768563',	'oxnewstlerinfo',	1,	1,	0,	1,	1,	'',	'Neuigkeiten bei uns',	'<div>Mit dem {{  oxcmp_shop.oxshops__oxname.value  }}-Newsletter alle paar Wochen. <br>\r\nMit Tipps, Infos, Aktionen ... <br>\r\n<br>\r\nDas Abo kann jederzeit durch Austragen der E-Mail-Adresse beendet werden. <br>\r\nEine <span class=\"newsletter_title\">Weitergabe Ihrer Daten an Dritte lehnen wir ab</span>. <br>\r\n<br>\r\nSie bekommen zur Bestätigung nach dem Abonnement eine E-Mail - so stellen wir sicher, dass kein Unbefugter Sie in unseren Newsletter eintragen kann (sog. \"Double Opt-In\").<br>\r\n<br>\r\n</div>',	'newsletter info',	'<p>Stay in touch with the periodic {{  oxcmp_shop.oxshops__oxname.value  }}-newsletter every couple of weeks. We gladly inform you about recent tips, promotions and new products.</p>\r\n<p>You can unsubscribe any time from the newsletter.</p>\r\n<p>We strictly refuse <span class=\"newsletter_title\">transferring your data to 3rd parties</span>.</p>\r\n<p>For subscription we use the so called &quot;double opt-in&quot; procedure to guarantee that no unauthorized person will register with your e-mail address.</p>',	1,	'',	'',	1,	'',	'',	'30e44ab83fdee7564.23264141',	'CMSFOLDER_USERINFO',	'',	'2024-12-06 12:20:29');

DROP TABLE IF EXISTS `oxcountry`;
CREATE TABLE `oxcountry` (
                             `OXID` char(32) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL COMMENT 'Country id',
                             `OXACTIVE` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Active',
                             `OXTITLE` varchar(128) NOT NULL DEFAULT '' COMMENT 'Title (multilanguage)',
                             `OXISOALPHA2` char(2) NOT NULL DEFAULT '' COMMENT 'ISO 3166-1 alpha-2',
                             `OXISOALPHA3` char(3) NOT NULL DEFAULT '' COMMENT 'ISO 3166-1 alpha-3',
                             `OXUNNUM3` char(3) NOT NULL DEFAULT '' COMMENT 'ISO 3166-1 numeric',
                             `OXVATINPREFIX` char(2) NOT NULL DEFAULT '' COMMENT 'VAT identification number prefix',
                             `OXORDER` int(11) NOT NULL DEFAULT '9999' COMMENT 'Sorting',
                             `OXSHORTDESC` varchar(255) NOT NULL DEFAULT '' COMMENT 'Short description (multilanguage)',
                             `OXLONGDESC` varchar(255) NOT NULL DEFAULT '' COMMENT 'Long description (multilanguage)',
                             `OXTITLE_1` varchar(128) NOT NULL DEFAULT '',
                             `OXTITLE_2` varchar(128) NOT NULL DEFAULT '',
                             `OXTITLE_3` varchar(128) NOT NULL DEFAULT '',
                             `OXSHORTDESC_1` varchar(255) NOT NULL DEFAULT '',
                             `OXSHORTDESC_2` varchar(255) NOT NULL DEFAULT '',
                             `OXSHORTDESC_3` varchar(255) NOT NULL DEFAULT '',
                             `OXLONGDESC_1` varchar(255) NOT NULL,
                             `OXLONGDESC_2` varchar(255) NOT NULL,
                             `OXLONGDESC_3` varchar(255) NOT NULL,
                             `OXVATSTATUS` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Vat status: 0 - Do not bill VAT, 1 - Do not bill VAT only if provided valid VAT ID',
                             `OXTIMESTAMP` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Timestamp',
                             PRIMARY KEY (`OXID`),
                             KEY `OXACTIVE` (`OXACTIVE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Countries list';

